const tabId = 480038377;
const audioHref = await browserjs(tabId, () => {
  const link = document.querySelector("a[href*='audio']");
  if (link) return link.href;
  // check inside iframes
  for (const iframe of document.querySelectorAll("iframe")) {
    try {
      const l = iframe.contentDocument?.querySelector("a[href*='audio']") || iframe.contentDocument?.querySelector("audio source") || iframe.contentDocument?.querySelector("audio");
      if (l) return l.src || l.href;
    } catch (e) {}
  }
  return null;
});
console.log("Audio href:", audioHref);

