const slidesgoTabId = 480038387;
await tool.navigate({ tabId: slidesgoTabId, url: "https://slidesgo.com/theme/notebook-lesson" });
await tool.wait_for({ tabId: slidesgoTabId, condition: "load_state", value: "load", timeout_ms: 15000 });

const templateInfo = await browserjs(slidesgoTabId, () => {
  const title = document.querySelector("h1")?.textContent?.trim();
  const url = window.location.href;
  const downloadBtns = Array.from(document.querySelectorAll("button, a, .download-btn, [data-format]")).map(el => ({
    text: el.textContent?.trim(),
    format: el.getAttribute("data-format") || el.getAttribute("aria-label")
  })).filter(b => b.text?.toLowerCase().includes("google slides") || b.text?.toLowerCase().includes("powerpoint") || b.format?.toLowerCase().includes("google") || b.format?.toLowerCase().includes("powerpoint"));

  const formatsText = Array.from(document.querySelectorAll("*")).filter(el => el.children.length === 0 && (el.textContent.includes("Google Slides") || el.textContent.includes("PowerPoint"))).map(el => el.textContent.trim());

  const previews = Array.from(document.querySelectorAll("img")).filter(img => img.src.includes("storage") || img.src.includes("slides")).map(img => img.src).slice(0, 5);

  return { title, url, downloadBtns, formatsText: Array.from(new Set(formatsText)), previews };
});
console.log("Template info:", JSON.stringify(templateInfo, null, 2));

