const bionicTabId = 480038388;
const mdResult = await browserjs(bionicTabId, () => {
  // Let's check the copy markdown button or function
  const bionicEl = document.querySelector(".bionic-reading");
  if (!bionicEl) return null;
  // Let's convert the spans/b tags to markdown format
  const spans = Array.from(bionicEl.querySelectorAll("span"));
  const mdWords = spans.map(s => {
    const boldText = s.querySelector("b, strong")?.textContent || "";
    const normalText = s.textContent.replace(boldText, "");
    return `**${boldText}**${normalText}`;
  });
  return mdWords.join(" ");
});
